import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock

class AccountStore {
    private val mutex = Mutex()
    private var balances: Map<String, Long> = emptyMap()

    suspend fun transfer(from: String, to: String, amt: Long): Boolean = mutex.withLock {
        val b = balances
        if ((b[from] ?: 0L) < amt) return@withLock false
        balances = b + (from to (b[from]!! - amt)) + (to to ((b[to] ?: 0L) + amt))
        true        // one atomic swap of an immutable value: no ABA, no reclamation
    }
}
